package com.bank.core;

import java.math.BigDecimal;
import java.util.Objects;

public class Account {
    private final String accountId;
    private final String holderName;
    private final String nickname; // may be null
    private final BigDecimal balance;

    public Account(String accountId, String holderName, String nickname, BigDecimal balance) {
        // FAIL-FAST: enforce invariants at construction with clear messages.
        this.accountId = Objects.requireNonNull(accountId, "accountId must not be null");
        this.holderName = Objects.requireNonNull(holderName, "holderName must not be null");
        this.nickname = nickname; // allowed to be null
        this.balance = Objects.requireNonNull(balance, "balance must not be null");
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Account)) return false;
        Account other = (Account) o;
        // NULL-SAFE comparison building blocks.
        return Objects.equals(accountId, other.accountId)
            && Objects.equals(holderName, other.holderName);
    }

    @Override
    public int hashCode() {
        return Objects.hash(accountId, holderName); // combined, null-safe
    }

    public String getAccountId() { return accountId; }
    public String getNickname() { return nickname; }
    public BigDecimal getBalance() { return balance; }
}
