package com.bank.core;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.logging.*;
import java.util.stream.Collectors;

public class ObjectsUtilDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", null, new BigDecimal("1000000.00"));

        // requireNonNull fail-fast
        try {
            new Account(null, "Ghost", "nick", new BigDecimal("1"));
        } catch (NullPointerException e) {
            log.log(Level.SEVERE, "Fail-fast on null accountId", e);
        }

        // Objects.equals null-safe (nickname is null)
        boolean sameNick = Objects.equals(rajesh.getNickname(), null);
        log.info(() -> "Objects.equals(nickname, null) → " + sameNick);

        // Objects.toString with default
        String shownNick = Objects.toString(rajesh.getNickname(), "N/A");
        log.info(() -> "nickname shown as → " + shownNick);

        // Objects::nonNull predicate in a stream
        List<String> ids = Arrays.asList("SAV2001", null, "CUR3001", null);
        List<String> clean = ids.stream().filter(Objects::nonNull).collect(Collectors.toList());
        log.info(() -> "non-null ids → " + clean);
    }
}
